import { afterEach, beforeEach, describe, expect, it, type Mock, vi } from "vitest";

vi.mock("../runtime-input.js", () => ({
	resolveRuntimeInput: vi.fn(),
}));

import { ExecutionError } from "../error.js";
import { resolveRuntimeInput } from "../runtime-input.js";
import { Worker } from "../worker.js";
import {
	createWebhookCapability,
	type WebhookEvent,
	type WebhookVerifyHandler,
} from "./webhook.js";

const argumentEvents: WebhookEvent[] = [
	{
		deliveryId: "argument",
		body: { source: "argument" },
		rawBody: '{"source":"argument"}',
		headers: {},
		method: "POST",
	},
];

describe("Worker.webhook", () => {
	let stdoutSpy: Mock<typeof process.stdout.write>;
	const resolveRuntimeInputMock = vi.mocked(resolveRuntimeInput);

	beforeEach(() => {
		stdoutSpy = vi.spyOn(process.stdout, "write").mockImplementation(() => true);
		resolveRuntimeInputMock.mockImplementation(async (fallback) => fallback);
	});

	afterEach(() => {
		vi.restoreAllMocks();
	});

	it("uses file-backed events instead of argument events", async () => {
		const execute = vi.fn();
		const capability = createWebhookCapability("incoming", {
			title: "Incoming",
			description: "Process an incoming webhook",
			execute,
		});
		const fileEvents: WebhookEvent[] = [
			{
				deliveryId: "file",
				body: { source: "file" },
				rawBody: '{"source":"file"}',
				headers: {},
				method: "POST",
			},
		];
		resolveRuntimeInputMock.mockResolvedValue(fileEvents);

		await capability.handler(argumentEvents, { concreteOutput: true });

		expect(execute).toHaveBeenCalledWith(fileEvents, expect.anything());
	});

	it("reports file-backed input failures through the existing webhook error path", async () => {
		const execute = vi.fn();
		const capability = createWebhookCapability("incoming", {
			title: "Incoming",
			description: "Process an incoming webhook",
			execute,
		});
		resolveRuntimeInputMock.mockRejectedValue(new SyntaxError("Unexpected end of JSON input"));

		await expect(capability.handler(argumentEvents)).rejects.toBeInstanceOf(ExecutionError);
		expect(execute).not.toHaveBeenCalled();
		expect(stdoutSpy).toHaveBeenCalledWith(
			expect.stringContaining(
				`"_tag":"error","error":{"name":"ExecutionError","message":"Error during worker execution: SyntaxError: Unexpected end of JSON input"`,
			),
		);
	});
});

describe("Worker.webhook verify", () => {
	const resolveRuntimeInputMock = vi.mocked(resolveRuntimeInput);
	let stdoutSpy: Mock<typeof process.stdout.write>;

	beforeEach(() => {
		stdoutSpy = vi.spyOn(process.stdout, "write").mockImplementation(() => true);
		resolveRuntimeInputMock.mockImplementation(async (fallback) => fallback);
	});

	afterEach(() => {
		vi.restoreAllMocks();
	});

	const verifyRequest = {
		method: "POST" as const,
		url: "https://123456.webhook.notionusercontent.com/webhooks/worker/s/w/u/incoming",
		query: {},
		headers: { "x-signature": "sig" },
		rawBody: '{"challenge":"abc"}',
	};

	it("marks the capability config with hasVerify when a verify handler is set", () => {
		const capability = createWebhookCapability("incoming", {
			title: "Incoming",
			description: "Process an incoming webhook",
			verify: () => ({ status: 200 }),
			execute: async () => {},
		});

		expect(capability.config).toEqual({
			title: "Incoming",
			description: "Process an incoming webhook",
			hasVerify: true,
		});
	});

	it("omits hasVerify from the config when no verify handler is set", () => {
		const capability = createWebhookCapability("incoming", {
			title: "Incoming",
			description: "Process an incoming webhook",
			execute: async () => {},
		});

		expect("hasVerify" in capability.config).toBe(false);
	});

	it("dispatches a verify invocation to the verify handler, not execute", async () => {
		const execute = vi.fn();
		const verify: WebhookVerifyHandler = (request) => ({
			status: 200,
			body: (JSON.parse(request.rawBody) as { challenge: string }).challenge,
			contentType: "text/plain",
		});
		const capability = createWebhookCapability("incoming", {
			title: "Incoming",
			description: "Process an incoming webhook",
			verify,
			execute,
		});

		const response = await capability.handler({ request: verifyRequest }, { concreteOutput: true });

		expect(response).toEqual({ status: 200, body: "abc", contentType: "text/plain" });
		expect(execute).not.toHaveBeenCalled();
	});

	it("passes the capability context to the verify handler", async () => {
		let receivedContext: unknown;
		const capability = createWebhookCapability("incoming", {
			title: "Incoming",
			description: "Process an incoming webhook",
			verify: (_request, context) => {
				receivedContext = context;
				return { status: 200 };
			},
			execute: async () => {},
		});

		await capability.handler({ request: verifyRequest }, { concreteOutput: true });

		expect(receivedContext).toHaveProperty("notion");
	});

	it("writes the verify response as a success output without concreteOutput", async () => {
		const capability = createWebhookCapability("incoming", {
			title: "Incoming",
			description: "Process an incoming webhook",
			verify: () => ({ status: 401 }),
			execute: async () => {},
		});

		await capability.handler({ request: verifyRequest });

		expect(stdoutSpy).toHaveBeenCalledWith(
			expect.stringContaining('"_tag":"success","value":{"status":401}'),
		);
	});

	it("runs in the worker bundle, so verify handlers may capture module scope", async () => {
		const signingSecret = "shh";
		const capability = createWebhookCapability("incoming", {
			title: "Incoming",
			description: "Process an incoming webhook",
			verify: (request) => ({
				status: request.headers["x-signature"] === signingSecret ? 200 : 401,
			}),
			execute: async () => {},
		});

		const response = await capability.handler(
			{ request: { ...verifyRequest, headers: { "x-signature": "shh" } } },
			{ concreteOutput: true },
		);

		expect(response).toEqual({ status: 200 });
	});

	it("still dispatches event arrays to execute when verify is configured", async () => {
		const execute = vi.fn();
		const capability = createWebhookCapability("incoming", {
			title: "Incoming",
			description: "Process an incoming webhook",
			verify: () => ({ status: 200 }),
			execute,
		});

		const result = await capability.handler(argumentEvents, { concreteOutput: true });

		expect(result).toEqual({ status: "success" });
		expect(execute).toHaveBeenCalledWith(argumentEvents, expect.anything());
	});

	it("rejects a verify invocation when no verify handler is declared", async () => {
		const execute = vi.fn();
		const capability = createWebhookCapability("incoming", {
			title: "Incoming",
			description: "Process an incoming webhook",
			execute,
		});

		await expect(
			capability.handler({ request: verifyRequest }, { concreteOutput: true }),
		).rejects.toThrow(/does not declare a verify handler/);
		expect(execute).not.toHaveBeenCalled();
	});

	it("round-trips hasVerify through the JSON-serialized worker manifest", () => {
		const worker = new Worker();
		worker.webhook("incoming", {
			title: "Incoming",
			description: "Process an incoming webhook",
			verify: () => ({ status: 200 }),
			execute: async () => {},
		});

		const manifest = JSON.parse(JSON.stringify(worker.manifest)) as {
			capabilities: Array<{ key: string; config: { hasVerify?: unknown } }>;
		};
		const webhook = manifest.capabilities.find((capability) => capability.key === "incoming");

		expect(webhook?.config.hasVerify).toBe(true);
	});
});
